    'user_id': 'user_id', 'id': 'user_id', 'userId': 'user_id',
    'email': 'email', 'email_address': 'email',
    'full_name': 'name', 'name': 'name', 'userName': 'name',
    'registration_date': 'created_date', 'created_at': 'created_date', 'joined': 'created_date',
}

def normalize(rec):
    out = {}
    for k, v in rec.items():
        nk = MAP.get(k)
        if nk:
            out[nk] = v
    return out

def to_date(v):
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%m/%d/%Y', '%d/%m/%Y', '%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S'):
        try:
            return datetime.strptime(str(v), fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return str(v)

with open('/data/source_a/users.json') as f:
    a = [normalize(r) for r in json.load(f)]
with open('/data/source_b/users.csv') as f:
    b = [normalize(r) for r in csv.DictReader(f)]
c = [normalize(r) for r in pq.read_table('/data/source_c/users.parquet').to_pylist()]

for data in (a, b, c):
    for r in data:
        r['user_id'] = int(r['user_id'])
        r['created_date'] = to_date(r['created_date'])

# Priority: source_a > source_b > source_c
sources = [('source_a', a), ('source_b', b), ('source_c', c)]
FIELDS = ['name', 'email', 'created_date']

merged = {}      # user_id -> {field: value}
conflicts = []   # list of conflict dicts

# Collect all user_ids
all_ids = set()
for _, data in sources:
    for r in data:
        all_ids.add(r['user_id'])

for uid in sorted(all_ids):
    per_source = {}
    for sname, data in sources:
        for r in data:
            if r['user_id'] == uid:
                per_source[sname] = r
                break
    # Select values by priority
    row = {'user_id': uid}
    for field in FIELDS:
        values = {}
        for sname, _ in sources:
            if sname in per_source and field in per_source[sname]:
                values[sname] = per_source[sname][field]
        # Select by priority
        selected = None
        for sname, _ in sources:
            if sname in values:
                selected = values[sname]
                break
        row[field] = selected
        # Conflict: more than one source has a different value
        distinct = set()
        for v in values.values():
            distinct.add(v)
        if len(distinct) > 1:
            conflicts.append({
                'user_id': uid,
                'field': field,
                'values': {k: values.get(k) for k in ['source_a','source_b','source_c'] if k in values},
                'selected': selected,
            })
    # status (optional, only source_a has it)
    if 'source_a' in per_source and 'status' in per_source['source_a']:
        row['status'] = per_source['source_a']['status']
    merged[uid] = row

print("Merged users:")
for uid, row in merged.items():
    print(row)
print("\nConflicts:", len(conflicts))
